-- 只读，排除13精确新身份后核对全部52435旧行；两新Gross仅由本批原取消服务删除，已另存原事实。
SELECT c.relname table_name,(xpath('/row/row_count/text()',x.doc))[1]::text row_count,(xpath('/row/data_md5/text()',x.doc))[1]::text data_md5 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL (SELECT query_to_xml(format('SELECT count(*) AS row_count, md5(coalesce(string_agg(to_jsonb(t)::text, chr(10) ORDER BY to_jsonb(t)::text), '''')) AS data_md5 FROM public.%I t%s',c.relname,CASE c.relname WHEN 'after_sales_header' THEN ' WHERE NOT (uid IN (''18bd9715-a372-4d43-9569-76f5cd25c528''))' WHEN 'after_sales_line' THEN ' WHERE NOT (uid IN (''18bd9715-a372-4d43-9569-76f5cd25c529'',''18bd9715-a372-4d43-9569-76f5cd25c52a''))' WHEN 'business_operation_log' THEN ' WHERE NOT (uid IN (''2759a098-ce48-47fb-ae64-4a35034e902b'',''28c60709-b90d-4497-bc85-4a35034e7d4d'',''378d0085-f49e-4954-8aa8-4a35034e571c'',''4afa8d9e-c7e6-4bf4-b1de-4a350352f4fd'',''7424c9ba-abdb-4810-8fdb-4a35034e9022''))' WHEN 'command_receipt' THEN ' WHERE NOT (uid IN (''b0546784-ec02-4329-9221-4a350352f517'',''c4cbe55a-57cb-4a7c-9355-4a35034e902e'',''e1ddc8be-7a8b-4ed6-bbc7-4a35034e7d4e'',''f200071e-1f4f-4504-a114-4a35034e572c''))' WHEN 'document_sequence' THEN ' WHERE NOT (uid IN (''fc6a5a03-5328-40a4-9778-4a35034e5700''))' ELSE '' END),false,true,'') doc) x WHERE n.nspname='public' AND c.relkind='r' ORDER BY c.relname
